def algorithm(func, dim, lb, ub, budget, rng):
    population_size = 50
    max_iter = int(budget / population_size)
    bounds = [(lb, ub) for _ in range(dim)]

    def differential_evolution(bounds, func, population_size, max_iter):
        x0 = np.random.rand(population_size, dim) * (ub - lb) + lb
        pop_best = x0[np.argmin([func(x) for x in x0]), :]

        for _ in range(max_iter):
            for i in range(population_size):
                n1, n2, n3 = np.random.choice(population_size, 3, replace=False)
                mutant = pop_best + rng.normal(size=(dim,)) * (x0[n1] - x0[n2]) + rng.normal(size=(dim,)) * (x0[n2] - x0[n3])
                mutant = 0.5 * (ub + lb) + rng.uniform(size=(dim), low=-1, high=1) * (mutant - pop_best)

                if func(mutant) < func(pop_best):
                    pop_best = mutant

        return pop_best

    grid_size = int(np.ceil((ub - lb) / 0.5)) + 1
    x_grid = np.linspace(lb, ub, grid_size)

    def grid_search(bounds, func, x_grid):
        X, Y = np.meshgrid(x_grid, x_grid)
        candidates = (X.flatten()[:, None] * (ub - lb) + lb).repeat(dim-1, axis=1)

        # Clip candidates to bounds
        for i in range(dim):
            candidates[:, i] = np.clip(candidates[:, i], bounds[i][0], bounds[i][1])

        return candidates[np.argmin([func(x) for x in candidates])]

    best_solution = None

    for _ in range(max_iter):
        pop_best = differential_evolution(bounds, func, population_size, max_iter)
        grid_best = grid_search(bounds, func, x_grid)

        if func(pop_best) < func(grid_best):
            best_solution = pop_best
        else:
            best_solution = grid_best

    return best_solution

def algorithm(func, dim, lb, ub, budget, rng):
    def clip_candidate(candidate, lb, ub):
        return np.clip(candidate, lb, ub)

    def generate_new_candidate(parent, sigma):
        return parent + rng.normal(size=dim) * sigma

    def evaluate_candidate(candidate):
        return func(candidate)

    population_size = 50
    initial_population = rng.uniform(lb, ub, size=(population_size, dim))
    population = [clip_candidate(individual, lb, ub) for individual in initial_population]
    best_individual = np.inf
    best_position = None

    for _ in range(budget):
        sigma = 0.1 / (2 + rng.uniform(0, 1))

        new_population = []
        for individual in population:
            candidate = generate_new_candidate(individual, sigma)
            new_population.append(clip_candidate(candidate, lb, ub))
            if evaluate_candidate(candidate) < best_individual:
                best_individual = evaluate_candidate(candidate)
                best_position = candidate

        population = new_population
        if rng.uniform(0, 1) > 0.9:
            for individual in population:
                sigma *= 1 + rng.uniform(-0.5, 0.5)

    return best_position

